    }
  ],
  "unresolvedIntentions": [
    {
      "id": "he-goal",
      "summary": "把冷藏药送到灯塔诊所"
    },
    {
      "id": "he-int3",
      "summary": "先确保病人稳定，再核对蓝签账页年月、页码与签章；暂不交出账页"
    }
  ],
  "privateMisbeliefs": []
}"
}

